// Evolved atomic batch approval with audit logging and scoped idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"strings"
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Check for idempotent replay within scope: operation+tenant+actor+key
		var existingResponse string
		err = tx.QueryRow(ctx, `SELECT response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation='bulk-approve.v3' AND key=$3`,
			u.Tenant, u.User, key).Scan(&existingResponse)
		if err == nil {
			// Key exists - check if it's for the same target set
			var existingResult protocol.Result
			if err := json.Unmarshal([]byte(existingResponse), &existingResult); err != nil {
				return protocol.Result{}, false, err
			}
			// Verify the target sets match - compute requestHash for the existing approval
			expectedHash := computeRequestHash(ids)
			// Query the actual hash stored for this key
			var storedHash string
			err = tx.QueryRow(ctx, `SELECT "requestHash" FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation='bulk-approve.v3' AND key=$3`,
				u.Tenant, u.User, key).Scan(&storedHash)
			if err != nil {
				return protocol.Result{}, false, err
			}
			if storedHash != expectedHash {
				// Same key, different target set - return 409
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			// Same key, same targets - idempotent replay
			return existingResult, true, nil
		} else if err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		// Lock and validate all targets
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Compute requestHash for all IDs
		requestHash := computeRequestHash(ids)

		// Create ActionRequest record (scoped by operation+tenant+actor+key)
		response := protocol.Result{ApprovedIDs: ids}
		responseJSON, err := json.Marshal(response)
		if err != nil {
			return protocol.Result{}, false, err
		}

		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response) VALUES ($1,$2,$3,$4,$5,$6)`,
			u.Tenant, u.User, "bulk-approve.v3", key, requestHash, string(responseJSON))
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Update all Purchase records
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Create ApprovalAudit records for each approved purchase
		for _, id := range ids {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus") VALUES ($1,$2,$3,$4,$5,$6,$7)`,
				u.Tenant, id, u.User, "bulk-approve.v3", key, "submitted", "approved")
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return response, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

// computeRequestHash computes SHA-256 of the request format:
// "bulk-approve.v3\n" + each ID formatted as "<UTF-8_byte_length>:<ID>"
func computeRequestHash(ids []string) string {
	h := sha256.New()
	h.Write([]byte("bulk-approve.v3\n"))
	for _, id := range ids {
		// IDs are already sorted and validated by canonical() in protocol
		idBytes := []byte(id)
		h.Write([]byte(fmt.Sprintf("%d:%s", len(idBytes), id)))
	}
	return hex.EncodeToString(h.Sum(nil))
}

